<?php use LipePool\Security\Csrf; use LipePool\Support\View; $labels = ['requested'=>'Solicitados','completed'=>'Concluídos','cancelled'=>'Cancelados','all'=>'Todos']; ?>
<section class="page-heading container"><p class="eyebrow">Área administrativa</p><h1>Agenda</h1><p class="lead">Acompanhe as solicitações e atualize o estado dos atendimentos.</p></section>
<section class="container section"><div class="filter-row"><nav class="filter-tabs" aria-label="Filtrar status"><?php foreach ($labels as $key => $label): ?><a class="<?= $status === $key ? 'is-active' : '' ?>" href="/admin/agenda?status=<?= View::escape($key) ?>"><?= View::escape($label) ?></a><?php endforeach; ?></nav><a class="text-link" href="/admin/clientes">Ver clientes →</a></div>
<?php if (!$appointments): ?><div class="empty-state"><h2>Nenhuma solicitação nesta lista</h2></div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Cliente</th><th>Serviço</th><th>Data / hora</th><th>Observações</th><th>Status</th><th>Ações</th></tr></thead><tbody>
<?php foreach ($appointments as $a): ?><tr><td><strong><?= View::escape($a['customer_name']) ?></strong><br><a href="mailto:<?= View::escape($a['customer_email']) ?>"><?= View::escape($a['customer_email']) ?></a><br><?= View::escape($a['customer_phone']) ?></td><td><?= View::escape($a['service_name']) ?></td><td><?= View::escape(date('d/m/Y', strtotime($a['appointment_date']))) ?><br><?= View::escape(substr($a['appointment_time'],0,5)) ?></td><td><?= View::escape($a['notes'] ?: '—') ?></td><td><span class="status status-<?= View::escape($a['status']) ?>"><?= View::escape($labels[$a['status']] ?? $a['status']) ?></span></td><td><?php if ($a['status'] === 'requested'): ?><div class="action-stack"><form method="post" action="/admin/agendamentos/<?= (int)$a['id'] ?>/concluir"><input type="hidden" name="_csrf" value="<?= View::escape(Csrf::token()) ?>"><button class="button button-primary button-small" type="submit">Concluir</button></form><form method="post" action="/admin/agendamentos/<?= (int)$a['id'] ?>/cancelar"><input type="hidden" name="_csrf" value="<?= View::escape(Csrf::token()) ?>"><button class="button button-danger button-small" type="submit">Cancelar</button></form></div><?php else: ?>—<?php endif; ?></td></tr><?php endforeach; ?>
</tbody></table></div><?php endif; ?></section>
